"""六个批训练入口统一重构后的等价性验证。

1) 新实现每种 (入口 × BN/GN × Dropout/Dropout2D × pool) 一次完成 vs
   逐边界分段：losses/grad_norms、八组参数、优化器状态、BN 运行统计、
   Dropout/Dropout2D 随机状态与掩码、GroupNorm 缓存、终态逐项相同。
2) BN+Dropout 路径下新实现与重构前模块 (/tmp/baseline/convnet_orig.py)
   的全部返回值与层状态逐项相同。
"""
import copy
import importlib.util
import math
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)


def load_module(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


cn = load_module("convnet_new", os.path.join(HERE, "convnet.py"))
old = load_module("convnet_orig", "/tmp/baseline/convnet_orig.py")

X, LABELS, _ = cn._load_bench_samples(os.path.join(HERE, "data", "tiny.csv"))
N = len(X)


def build_layers(mod, norm_kind, drop_kind, pool_kind):
    conv = mod.Conv2D(mod._deep_copy(mod._CNN_CONV_INIT), [0.0] * 2)
    if norm_kind == "bn":
        norm = mod.BatchNorm2D(
            mod._deep_copy(mod._NORM_GAMMA_INIT),
            mod._deep_copy(mod._NORM_BETA_INIT),
            mod._NORM_EPS, mod._NORM_MOMENTUM,
        )
    else:
        norm = mod.GroupNorm2D(
            1,
            mod._deep_copy(mod._NORM_GAMMA_INIT),
            mod._deep_copy(mod._NORM_BETA_INIT),
            mod._NORM_EPS,
        )
    if drop_kind == "d":
        drop = mod.Dropout(mod._NORM_DROPOUT_P, mod._NORM_DROPOUT_SEED)
    else:
        drop = mod.Dropout2D(mod._NORM_DROPOUT_P, mod._NORM_DROPOUT_SEED)
    if pool_kind == "max":
        pool = mod.MaxPool2D(2, 2, 0)
    elif pool_kind == "avg":
        pool = mod.AdaptiveAvgPool2D((1, 1))
    else:
        pool = mod.AdaptiveMaxPool2D((1, 1))
    return [
        conv, norm, drop, pool, mod.Flatten(),
        mod.Linear(mod._deep_copy(mod._BD_LINEAR1_INIT), [0.0] * 2),
        mod.ReLU(),
        mod.Linear(mod._deep_copy(mod._CNN_LINEAR_INIT), [0.0] * 2),
        mod.SoftmaxCrossEntropy(),
    ]


PARAM_ATTRS = (
    (0, "_weights"), (0, "_bias"),
    (1, "_gamma"), (1, "_beta"),
    (5, "_weights"), (5, "_bias"),
    (7, "_weights"), (7, "_bias"),
)


def snapshot(mod, layers):
    """深快照全部九层状态（含缓存、随机状态、BN 统计）与八组参数。"""
    return copy.deepcopy([dict(l.__dict__) for l in layers])


def assert_same_layers(a_layers, b_layers, tag):
    a = [dict(l.__dict__) for l in a_layers]
    b = [dict(l.__dict__) for l in b_layers]
    if a != b:
        # 找出第一个不同字段
        for i, (da, db) in enumerate(zip(a, b)):
            for k in da:
                if da[k] != db[k]:
                    raise AssertionError(
                        "%s: layer %d attr %s differs\n a=%r\n b=%r"
                        % (tag, i, k, da[k], db[k])
                    )
        raise AssertionError(tag + ": layer state differs")


def assert_same_value(a, b, tag, path=""):
    if isinstance(a, float) or isinstance(b, float):
        if a != b and not (math.isnan(a) and math.isnan(b)):
            raise AssertionError("%s%s: %r != %r" % (tag, path, a, b))
        return
    if isinstance(a, (list, tuple)) or isinstance(b, (list, tuple)):
        if type(a) is not type(b):
            raise AssertionError(
                "%s%s: type %r != %r" % (tag, path, type(a), type(b))
            )
        if len(a) != len(b):
            raise AssertionError(
                "%s%s: len %d != %d" % (tag, path, len(a), len(b))
            )
        for i, (x, y) in enumerate(zip(a, b)):
            assert_same_value(x, y, tag, "%s[%d]" % (path, i))
        return
    if a != b:
        raise AssertionError("%s%s: %r != %r" % (tag, path, a, b))


# 六个入口的配置：(名, 累积?, 模式)
ENTRIES = [
    ("train_deep_batches", False, "sgd"),
    ("train_deep_momentum_batches", False, "momentum"),
    ("train_deep_adam_batches", False, "adam"),
    ("train_deep_accum_batches", True, "sgd"),
    ("train_deep_momentum_accum_batches", True, "momentum"),
    ("train_deep_adam_accum_batches", True, "adam"),
]


def call(mod, name, layers, seed, **kw):
    return getattr(mod, name)(layers, X, LABELS, seed=seed, **kw)


def one_shot(mod, name, accumulate, layers, seed=3, clip=None):
    kw = {}
    if accumulate:
        kw.update(epochs=3, microbatch_size=2, accum_steps=2, clip=clip)
    else:
        kw.update(epochs=3, batch_size=2, clip=clip)
    if name == "train_deep_momentum_batches":
        kw["momentum"] = 0.8
    if name == "train_deep_momentum_accum_batches":
        kw["momentum"] = 0.8
    if name.endswith("adam_batches") or name == "train_deep_adam_accum_batches":
        kw["beta1"], kw["beta2"], kw["eps"] = 0.8, 0.9, 1e-7
    return call(mod, name, layers, seed, **kw)


def result_metrics(res):
    # 返回值去掉 state 部分（state 单独比较），保留 losses/gnorms/优化器状态
    return res


def segmented(mod, name, accumulate, layers, seed=3, clip=None):
    """逐边界分段完成与一次完成相同的训练量。"""
    common = dict(epochs=3, seed=seed)
    if accumulate:
        common.update(microbatch_size=2, accum_steps=2, clip=clip)
    else:
        common.update(batch_size=2, clip=clip)
    if name == "train_deep_momentum_batches":
        common["momentum"] = 0.8
    if name == "train_deep_momentum_accum_batches":
        common["momentum"] = 0.8
    if name.endswith("adam_batches") or name == "train_deep_adam_accum_batches":
        common.update(beta1=0.8, beta2=0.9, eps=1e-7)

    fn = getattr(mod, name)
    all_losses, all_norms = [], []
    opt = None  # (velocity) 或 (m,v,step)
    st = None
    step = 0
    # 每次只前进 1 个批 / 1 个更新 / 1 个微批，交替制造两种暂停边界
    tick = 0
    while True:
        kw = dict(common)
        if accumulate:
            # 交替：偶数拍限 1 个微批（可能停在八元态），奇数拍限 1 个更新
            if tick % 2 == 0:
                kw.update(state=st, max_microbatches=1)
            else:
                kw.update(state=st, max_updates=1)
        else:
            kw.update(state=st, max_batches=1)
        # 续传优化器状态
        if name in (
            "train_deep_momentum_batches",
            "train_deep_momentum_accum_batches",
        ):
            kw["velocity"] = opt
        elif name in (
            "train_deep_adam_batches",
            "train_deep_adam_accum_batches",
        ):
            kw["m"], kw["v"], kw["step"] = opt[0], opt[1], step
        res = fn(layers, X, LABELS, **kw)
        if name in (
            "train_deep_batches", "train_deep_accum_batches"
        ):
            losses, norms, st = res
        elif name in (
            "train_deep_momentum_batches",
            "train_deep_momentum_accum_batches",
        ):
            losses, norms, opt, st = res
        else:
            losses, norms, mnew, vnew, step, st = res
            opt = (mnew, vnew)
        all_losses += losses
        all_norms += norms
        if st[0] >= common["epochs"]:
            break
        tick += 1
        if tick > 1000:
            raise RuntimeError("segment loop runaway")
    # 组装与一次完成可比的返回形态
    if name in (
        "train_deep_batches", "train_deep_accum_batches"
    ):
        return all_losses, all_norms, st
    if name in (
        "train_deep_momentum_batches",
        "train_deep_momentum_accum_batches",
    ):
        return all_losses, all_norms, opt, st
    return all_losses, all_norms, opt[0], opt[1], step, st


def run_matrix(mod, pools=("max",)):
    for name, accumulate, mode in ENTRIES:
        for norm_kind in ("bn", "gn"):
            for drop_kind in ("d", "d2"):
                for pool_kind in pools:
                    tag = "%s/%s/%s/%s" % (
                        name, norm_kind, drop_kind, pool_kind
                    )
                    l1 = build_layers(mod, norm_kind, drop_kind, pool_kind)
                    l2 = build_layers(mod, norm_kind, drop_kind, pool_kind)
                    assert_same_layers(l1, l2, tag + " init")
                    r1 = one_shot(mod, name, accumulate, l1)
                    r2 = segmented(mod, name, accumulate, l2)
                    assert_same_value(r1, r2, tag, " result")
                    assert_same_layers(l1, l2, tag)
                    print("OK", tag)


print("== new module: one-shot vs segmented ==")
run_matrix(cn, pools=("max", "avg", "amax"))

print("== new vs old (BN + Dropout only, contracts shared) ==")
for name, accumulate, mode in ENTRIES:
    tag = name + " bn/d"
    l1 = build_layers(old, "bn", "d", "max")
    l2 = build_layers(cn, "bn", "d", "max")
    r1 = one_shot(old, name, accumulate, l1)
    r2 = one_shot(cn, name, accumulate, l2)
    assert_same_value(r1, r2, tag, " result")
    assert_same_layers(l1, l2, tag)

    # 分段路径同样对比
    l3 = build_layers(old, "bn", "d", "max")
    l4 = build_layers(cn, "bn", "d", "max")
    r3 = segmented(old, name, accumulate, l3)
    r4 = segmented(cn, name, accumulate, l4)
    assert_same_value(r3, r4, tag + " seg", " result")
