def build_layers(mod, norm_kind, drop_kind, pool_kind):
    conv = mod.Conv2D(mod._deep_copy(mod._CNN_CONV_INIT), [0.0] * 2)
    if norm_kind == "bn":
        norm = mod.BatchNorm2D(
            mod._deep_copy(mod._NORM_GAMMA_INIT),
            mod._deep_copy(mod._NORM_BETA_INIT),
            mod._NORM_EPS, mod._NORM_MOMENTUM,
        )
    else:
        norm = mod.GroupNorm2D(
            1,
            mod._deep_copy(mod._NORM_GAMMA_INIT),
            mod._deep_copy(mod._NORM_BETA_INIT),
            mod._NORM_EPS,
