def call(mod, name, layers, seed, **kw):
    return getattr(mod, name)(layers, X, LABELS, seed=seed, **kw)


def one_shot(mod, name, accumulate, layers, seed=3, clip=None):
    kw = {}
    if accumulate:
        kw.update(epochs=3, microbatch_size=2, accum_steps=2, clip=clip)
    else:
        kw.update(epochs=3, batch_size=2, clip=clip)
    if name == "train_deep_momentum_batches":
        kw["momentum"] = 0.8
    if name == "train_deep_momentum_accum_batches":
        kw["momentum"] = 0.8
    if name.endswith("adam_batches") or name == "train_deep_adam_accum_batches":
        kw["beta1"], kw["beta2"], kw["eps"] = 0.8, 0.9, 1e-7
    # 显式给一个用不完的预算，使 SGD 入口也回传终态（计算与无暂停完全
    # 相同，仅多一个 state 返回项），便于与分段结果逐项比较。
    if accumulate:
        kw["max_updates"] = 10 ** 6
    else:
        kw["max_batches"] = 10 ** 6
    return call(mod, name, layers, seed, **kw)


def result_metrics(res):
    # 返回值去掉 state 部分（state 单独比较），保留 losses/gnorms/优化器状态
    return res


def segmented(mod, name, accumulate, layers, seed=3, clip=None):
    """逐边界分段完成与一次完成相同的训练量。"""
    common = dict(epochs=3, seed=seed)
    if accumulate:
        common.update(microbatch_size=2, accum_steps=2, clip=clip)
    else:
        common.update(batch_size=2, clip=clip)
    if name == "train_deep_momentum_batches":
        common["momentum"] = 0.8
    if name == "train_deep_momentum_accum_batches":
        common["momentum"] = 0.8
    if name.endswith("adam_batches") or name == "train_deep_adam_accum_batches":
        common.update(beta1=0.8, beta2=0.9, eps=1e-7)

    fn = getattr(mod, name)
    all_losses, all_norms = [], []
    opt = None  # (velocity) 或 (m,v,step)
    st = None
    step = 0
    # 每次只前进 1 个批 / 1 个更新 / 1 个微批，交替制造两种暂停边界
    tick = 0
    while True:
        kw = dict(common)
        if accumulate:
            # 交替：偶数拍限 1 个微批（可能停在八元态），奇数拍限 1 个更新
            if tick % 2 == 0:
                kw.update(state=st, max_microbatches=1)
            else:
                kw.update(state=st, max_updates=1)
        else:
            kw.update(state=st, max_batches=1)
        # 续传优化器状态
        if name in (
            "train_deep_momentum_batches",
            "train_deep_momentum_accum_batches",
        ):
            kw["velocity"] = opt
        elif name in (
            "train_deep_adam_batches",
            "train_deep_adam_accum_batches",
        ):
            kw["m"], kw["v"], kw["step"] = opt[0], opt[1], step
        res = fn(layers, X, LABELS, **kw)
        if name in (
            "train_deep_batches", "train_deep_accum_batches"
        ):
            losses, norms, st = res
        elif name in (
            "train_deep_momentum_batches",
            "train_deep_momentum_accum_batches",
        ):
            losses, norms, opt, st = res
        else:
            losses, norms, mnew, vnew, step, st = res
            opt = (mnew, vnew)
        all_losses += losses
        all_norms += norms
        if st[0] >= common["epochs"]:
            break
        tick += 1
        if tick > 1000:
            raise RuntimeError("segment loop runaway")
    # 组装与一次完成可比的返回形态
    if name in (
        "train_deep_batches", "train_deep_accum_batches"
    ):
        return all_losses, all_norms, st
    if name in (
        "train_deep_momentum_batches",
        "train_deep_momentum_accum_batches",
    ):
        return all_losses, all_norms, opt, st
    return all_losses, all_norms, opt[0], opt[1], step, st


def run_matrix(mod, pools=("max",)):
    for name, accumulate, mode in ENTRIES:
        for norm_kind in ("bn", "gn"):
            for drop_kind in ("d", "d2"):
                for pool_kind in pools:
                    tag = "%s/%s/%s/%s" % (
                        name, norm_kind, drop_kind, pool_kind
                    )
                    l1 = build_layers(mod, norm_kind, drop_kind, pool_kind)
                    l2 = build_layers(mod, norm_kind, drop_kind, pool_kind)
                    assert_same_layers(l1, l2, tag + " init")
                    r1 = one_shot(mod, name, accumulate, l1)
                    r2 = segmented(mod, name, accumulate, l2)
                    assert_same_value(r1, r2, tag, " result")
                    assert_same_layers(l1, l2, tag)
                    print("OK", tag)


